function kthSmallest(root, k) {
  const stack = []
  let node = root
  while (node || stack.length > 0) {
    while (node) { // go as far left as possible
      stack.push(node)
      node = node.left
    }
    node = stack.pop() // the next value in sorted order
    k--
    if (k === 0) return node.val
    node = node.right
  }
  return null
}

