solution.javascript:
function buildTree(preorder, inorder) {
  const where = new Map(inorder.map((v, i) => [v, i])) // value -> inorder index
  let next = 0 // the next preorder value is the next root to build
  const build = (lo, hi) => { // build the subtree whose values are inorder[lo..hi]
    if (lo > hi) return null
    const value = preorder[next++]
    const node = new TreeNode(value)
    const mid = where.get(value)
    node.left = build(lo, mid - 1) // preorder lists the whole left subtree first
    node.right = build(mid + 1, hi)
    return node
  }
  return build(0, inorder.length - 1)
}

