function maxPathSum(root) {
  let best = root.val
  // Best sum of a downward path that starts at node (0 for an empty subtree).
  const gain = (node) => {
    if (!node) return 0
    const left = Math.max(gain(node.left), 0) // drop branches that only hurt
    const right = Math.max(gain(node.right), 0)
    best = Math.max(best, node.val + left + right) // the path that bends here
    return node.val + Math.max(left, right) // a parent can use only one branch
  }
  gain(root)
  return best
}

