    return ",".join(parts)


def deserialize(data):
    tokens = iter(data.split(","))

    def build():
        token = next(tokens)
        if token == "#":
            return None
        node = TreeNode(int(token))
        node.left = build()             # same order as serialize: node, left, right
        node.right = build()
        return node

    return build()


